from datetime import date
from math import floor


class Loyalty:
    def __init__(self) -> None:
        self._purchases = {}
        self._redemptions = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")

        points = floor(amount / 10)
        self._purchases.setdefault(customer, []).append((day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        earned = sum(
            points
            for purchase_day, points in self._purchases.get(customer, ())
            if (day - purchase_day).days >= 14
        )
        redeemed = sum(
            points
            for redemption_day, points in self._redemptions.get(customer, ())
            if redemption_day <= day
        )
        return earned - redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Redemption must be a positive multiple of 100")
        if self.balance(customer, day) < points:
            raise ValueError("Insufficient points")

        # A backdated redemption must not invalidate later redemptions.
        for redemption_day, _ in self._redemptions.get(customer, ()):
            if redemption_day > day and self.balance(customer, redemption_day) < points:
                raise ValueError("Redemption would invalidate a later redemption")

        self._redemptions.setdefault(customer, []).append((day, points))
